(async()=>{
 const s=Eam.s,queue=document.getElementById('role-queue');if(!queue)return;
 const taskQueue=[s.task,...s.taskInstances].filter(t=>t.assignee===s.person),pendingTasks=taskQueue.filter(t=>t.status==='pending').length;
 let discoveries,work,hazards,config;try{[discoveries,work,hazards,config]=await Promise.all([EamProblemApi.request('GET','/discoveries'),EamProblemApi.request('GET','/work-orders'),EamProblemApi.request('GET','/hazards'),EamProblemApi.request('GET','/work-config')]);}catch(e){Eam.text('role-note',e.message+'；业务队列读取失败，请刷新重试。');return;}const role=Eam.role(),open=discoveries.rows.filter(r=>!['archived','withdrawn','draft'].includes(r.status)).map(r=>({...r,reporterId:r.ownerId})),orders=work.rows.filter(o=>!['closed','cancelled'].includes(o.status)).map(o=>({...o,assignee:o.assigneeId}));
 document.querySelector('h1').textContent=role[1]+'工作台';Eam.text('role-note','当前人员：'+Eam.person().name+' / '+s.person+'。按模拟角色与任务关系展示；指标仅覆盖本会话。');
 role.slice(3).forEach((label,i)=>Eam.text('metric-label-'+i,label));
 const metrics={operator:[1,pendingTasks,open.filter(r=>r.reporterId===s.person).length,s.restrictions.filter(r=>r.status==='active').length],inspector:[1,pendingTasks,0,s.draft.temperature?1:0],technician:[orders.filter(o=>o.assignee===s.person).length,orders.filter(o=>o.status==='executing').length,orders.filter(o=>o.status==='technical_complete').length,'—'],supervisor:[1,open.filter(r=>r.status==='submitted').length,orders.filter(o=>o.status==='technical_complete').length,0],engineer:[1,'—',s.standardDraft?1:0,0],metrology:['—','—','—',open.filter(r=>r.status==='professional').length],quality:[open.filter(r=>r.status==='professional').length,open.length,'—','—'],safety:[1,s.restrictions.filter(r=>r.status==='active').length,s.restrictions.filter(r=>r.status==='active').length,'—'],spare:['—','—','—','—'],manager:['—',s.restrictions.filter(r=>r.status==='active').length,open.length,'—'],auditor:[s.events.length,open.length,'—',s.attachments.length],contractor:[orders.filter(o=>o.assignee===s.person).length,orders.filter(o=>o.assignee===s.person&&o.status==='technical_complete').length,orders.filter(o=>o.assignee===s.person&&o.reworkRequired).length,'—'],admin:['—',0,0,s.events.filter(e=>['standard','plan'].includes(e.objectType)).length]};
 metrics[s.role].forEach((v,i)=>Eam.text('metric-'+i,v));
 const guides={operator:['当班状态与异常上报','检查使用限制，发现异常先登记事实。',['device','inspection','defect']],inspector:['例行与专项点检','逐项提交，异常保留证据；不能覆盖已提交结果。',['inspection','plans','device']],technician:['本人指派工单','开工核验安全/资格；返工形成新修订，不能自验收。',['order','acceptance','device']],supervisor:['班组异常受理和验收','原因不明先检查，明确故障派工；无人承接时重新安排。',['defect','acceptance','plans']],engineer:['标准策略和设备管理','配置设备标准/路线，独立审批；关键状态改变记录原因。',['standards','plans','device']],metrology:['专业异常及计量限制','处置专业异常；本设备示例无测量用途，计量任务暂无来源。',['defect','device']],quality:['影响与专业处置','记录专业处置结论与依据，审核标准；未接批次来源显示未知。',['defect','standards','history']],safety:['风险限制与作业恢复','查看风险来源，独立放行留依据；不能把维修关闭等同解除限制。',['device','order','defect']],spare:['工单用料与来源单据','查看维修单的用料引用；库存、替代审批及同步尚未接入。',['order','device']],manager:['设备风险与经营摘要','查看限制、未闭环与工时；缺成本与有效运行时间不虚构指标。',['device','history']],auditor:['证据与历史版本','查看人员、时间、原始结果和返工版本；只读，不获得业务验收权。',['history','device']],contractor:['限定指派任务','仅能执行本人指派工单；必须有效资格和安全措施。',['order','device']],admin:['技术配置与模拟异常','查看模拟配置变更/版本冲突；系统管理员无业务批准权限。',['history','catalog']]};
 const [title,guide,links]=guides[s.role];Eam.text('role-guide',title+'：'+guide);
 const container=document.getElementById('role-links');for(const page of links){const button=document.createElement('button');if(page==='history'){button.textContent='设备履历';button.onclick=()=>Eam.go('device',{tab:'history'});container.append(button);continue;}button.dataset.page=({inspection:'inspection-list',defect:'abnormal-events',order:'order-list',standards:'standard-list',plans:'plan-list'}[page]||page);button.textContent=({device:'设备档案',inspection:'我的点检',defect:'异常处置',order:'工单',acceptance:'验收',standards:'标准',plans:'路线/计划',history:'履历',catalog:'原型范围'})[page];container.append(button);}
 if(['operator','inspector'].includes(s.role)){for(const task of [s.task,...s.taskInstances].filter(t=>t.assignee===s.person))Eam.row(queue,'例行 '+task.id,task.status==='complete'?'已完成 / 查看原结果':task.status==='cancelled'?'已取消':'待执行 / '+task.window,'inspection',{task:task.id});for(const check of s.checks.filter(c=>c.assignee===s.person))Eam.row(queue,'专项 '+check.id,check.status==='complete'?'已完成':check.method,'inspection',{tab:'special',check:check.id});}
 if(['technician','contractor','spare'].includes(s.role))for(const o of orders.filter(o=>s.role==='spare'||o.assignee===s.person))Eam.row(queue,o.id,(config.labels[o.status]||o.status)+' / '+o.scope,'order',{order:o.id});
 if(['supervisor','engineer','quality','metrology','safety'].includes(s.role))for(const r of open)Eam.row(queue,r.id,(config.labels[r.status]||r.status)+' / '+r.description,'abnormal-events',{id:r.id,...(['engineer','supervisor'].includes(s.role)&&r.status==='submitted'?{action:'triage'}:{})});
 if(s.role==='safety')for(const h of hazards.rows.filter(h=>h.status!=='closed'||h.restriction?.status==='active'))Eam.row(queue,h.id,h.description+' / '+(config.labels[h.status]||h.status),'hazards',{id:h.id});
 if(s.role==='supervisor')for(const o of orders.filter(o=>o.status==='technical_complete'))Eam.row(queue,'待验收 '+o.id,EamDomain.personName(o.assignee),'acceptance',{order:o.id});
 if(s.role==='engineer'&&s.standardDraft)Eam.row(queue,'标准草稿 '+s.standardDraft.revision,'等待独立审核','standards');
 if(['auditor','admin'].includes(s.role))for(const e of s.events.slice(0,5))Eam.row(queue,e.text,e.actor+' / '+e.time,'device',{tab:'history',source:e.id});
 if(s.role==='manager')Eam.row(queue,'设备全景风险摘要',open.length+'条未闭环，'+s.restrictions.filter(r=>r.status==='active').length+'条限制','device');
 if(!queue.children.length)Eam.row(queue,'当前角色暂无待处理记录',guide,links[0]);
})();
